static int fpr_lt(uint64_t x, uint64_t y) {
    int sx = (int)(x >> 63);
    int sy = (int)(y >> 63);
    int different = sx ^ sy;

    return (different & sx)
         | ((different ^ 1) & (sx ^ 1) & (x < y))
         | ((different ^ 1) & sx & (x > y));
}
